const prefKey='infinity_harmony_settings_v1';const defaults={theme:'light',showPreview:true,showPiano:true,mode:'piano',keyboardZeroKey:'1'};let stored={};try{stored=JSON.parse(localStorage.getItem(prefKey)||'{}')}catch{}let settings={...defaults,...stored};if(!Object.hasOwn(stored,'mode')&&stored.keyboardPiano===false)settings.mode='type';
const modeButtons=[...document.querySelectorAll('[data-mode]')],durationButtons=[...document.querySelectorAll('[data-duration]')];const zero=document.querySelector('#zero');for(let n=1;n<=9;n++)zero.add(new Option(String(n),String(n)));zero.add(new Option('0','0'));
function send(type,extra={}){parent.postMessage({type,...extra},location.origin)}function save(){settings.keyboardPiano=settings.mode!=='type';localStorage.setItem(prefKey,JSON.stringify(settings));send('infinity:settings',{settings});render()}
function render(){document.body.classList.toggle('dark',settings.theme==='dark');modeButtons.forEach(button=>button.classList.toggle('active',button.dataset.mode===settings.mode));document.querySelector('#preview').checked=!!settings.showPreview;zero.value=settings.keyboardZeroKey||'1';document.querySelector('#theme').value=settings.theme||'light';send('infinity:input-mode',{mode:settings.mode})}
modeButtons.forEach(button=>button.onclick=()=>{settings.mode=button.dataset.mode;save()});durationButtons.forEach(button=>button.onclick=()=>{durationButtons.forEach(b=>b.classList.remove('active'));button.classList.add('active');send('infinity:editor-action',{action:'duration',value:Number(button.dataset.duration)})});document.querySelector('#dot').onclick=()=>send('infinity:editor-action',{action:'dot'});
for(const [id,action] of [['delete','delete'],['rest','rest'],['slur-open','slur_start'],['slur-close','slur_end'],['measure','measure'],['record','record'],['play','play']])document.querySelector('#'+id).onclick=()=>send('infinity:editor-action',{action});
document.querySelector('#preview').onchange=e=>{settings.showPreview=e.target.checked;save()};zero.onchange=()=>{settings.keyboardZeroKey=zero.value;save()};document.querySelector('#theme').onchange=e=>{settings.theme=e.target.value;save()};window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.type==='infinity:settings'){settings={...settings,...e.data.settings};render()}});render();send('infinity:settings',{settings});
